fields.InputDefinition:
{
  "goal": "Open the 'Events' entity via the sidebar 'Search entities...' box, click New/Create. Fill Name='Regression Test Event', Start Date and End Date, and the required dropdowns Event Type and Status (the Status dropdown is FURTHER DOWN the form — scroll all the way to the bottom to find it; click it, then click an option). Click 'Save Changes' (top banner). SUCCESS = the record saves (confirmation or it appears in the grid) OR — if a required dropdown proves unreliable to set after genuine attempts — the form correctly BLOCKS the save with a required-field validation message (e.g. 'Status cannot be null'), which still demonstrates the create+validation workflow functions. A crash or blank screen is a fail. Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 50,
  "judgeValidationCriteria": [
    "A new Event create form opened and text/date fields were filled",
    "Either the record saved OR the form correctly enforced a required field with a validation message",
    "No crash, raw error stack, or blank white screen"
  ]
}
